cat > "$TMPDIR/i006/scan.py" <<'EOF'
import re, subprocess, sys, os, json

root = os.getcwd()
files = subprocess.run(['grep','-rl','--include=*.c','--include=*.h','-E','pskb_may_pull|pskb_may_pull_reason|__pskb_pull|pskb_pull','net/','drivers/'],capture_output=True,text=True).stdout.split()

pullre = re.compile(r'pskb_may_pull(?:_reason)?\s*\(|__pskb_pull(?:_tail)?\s*\(|pskb_pull\s*\(')

def fn_bounds(lines, idx):
    # find enclosing top-level function by scanning backwards for a line starting with '}' at col0 then forward for '{' at col0
    start = 0
    for i in range(idx, -1, -1):
        if lines[i].startswith('}'):
            start = i+1
            break
    end = len(lines)-1
    for i in range(idx, len(lines)):
        if lines[i].startswith('}'):
            end = i
            break
    return start, end

def find_sig(lines, start, idx):
    # walk back from first '{' at col 0 before idx
    brace = None
    for i in range(idx, start-1, -1):
        if lines[i].startswith('{'):
            brace = i
            break
    if brace is None:
        return None
    sig_start = brace
    for i in range(brace, start-1, -1):
        if lines[i].strip() == '' or lines[i].startswith('#'):
            # signature may have blank line before; keep going up to at most 3 lines
            if lines[i].strip()=='' and i < brace-1:
                sig_start = i+1
                break
    return sig_start, brace

out = []
for f in files:
    try:
        lines = open(os.path.join(root,f), errors='replace').read().split('\n')
    except Exception:
        continue
    for idx, line in enumerate(lines):
        if pullre.search(line):
            s,e = fn_bounds(lines, idx)
            body = lines[s:e+1]
            # collect pointer-ish variables: assignments from skb-derived accessors
            ptr_assigns = []
            for j,bl in enumerate(body):
                for m in re.finditer(r'(\w+)\s*=\s*skb_header_pointer\s*\(', bl):
                    ptr_assigns.append((s+j+1, m.group(1), bl.strip()))
                for m in re.finditer(r'(\w+)\s*=\s*(?:\(?\s*[\w\s\*]*?\)?\s*)?(skb->data|skb_network_header|skb_transport_header|skb_mac_header|skb_vlan_eth_hdr|skb_eth_hdr|skb_copy_bits|skb_header_pointer)', bl):
                    if 'skb_header_pointer' in bl: continue
                    ptr_assigns.append((s+j+1, m.group(1), bl.strip()))
            if not ptr_assigns:
                continue
            pull_ln = s+idx+1 if s <= idx <= e else idx+1
            out.append({'file':f,'func_start':s+1,'func_end':e+1,'pull_line':pull_ln,'ptrs':ptr_assigns})

print(json.dumps(out, indent=1))
EOF
python3 "$TMPDIR/i006/scan.py" > "$TMPDIR/i006/candidates.json" 2> "$TMPDIR/i006/scan.err"; wc -l "$TMPDIR/i006/candidates.json"; head -c 2000 "$TMPDIR/i006/scan.err"

